import React from 'react'
import { Col, Typography, Input, Form } from 'antd'
import { RowWithMargin } from '../../../../CommonComponents/index.style'
import { validationRules } from '../constants'

const { Text } = Typography

const UserFormFields = ({ getFieldDecorator }) => {
  return (
    <RowWithMargin gutter={8}>
      <Col span={24}><Text strong>User Details</Text></Col>
      <Col span={6}>
        <Form.Item
          label='User name'
        >
          {getFieldDecorator('user.name', {
            validateTrigger: 'onBlur',
            rules: validationRules.name
          })(
            <Input
              placeholder='Andrew..'
            />
          )}
        </Form.Item>
      </Col>
      <Col span={6}>
        <Form.Item
          label='Email'
        >
          {getFieldDecorator('user.work_email', {
            validateTrigger: 'onBlur',
            rules: validationRules.workEmail
          })(
            <Input
              placeholder='Andrew@pasarpolis.com'
            />
          )}
        </Form.Item>
      </Col>
      <Col span={6}>
        <Form.Item
          label='Phone'
        >
          {getFieldDecorator('user.phone', {
            validateTrigger: 'onBlur',
            rules: validationRules.phone
          })(
            <Input
              addonBefore='+62'
              placeholder='08777000000'
            />
          )}
        </Form.Item>
      </Col>
    </RowWithMargin>
  )
}

export default UserFormFields
