import { isBefore, isToday } from 'date-fns'

export const callWithTimeout = (fn) => {
  setTimeout(() => fn())
}

export function getEmployeeError (errors, values) {
  const errorObject = {}
  for (const key in values.employee) {
    errorObject[key] = {
      value: values.employee[key],
      errors: Array.isArray(errors.employee[key]) ? errors.employee[key].map(err => new Error(err)) : null
    }
  }
  return errorObject
}

export function disabledDate (current) {
  // Can not select days before today and today
  return current && isBefore(current, new Date()) && !isToday(current)
}

export const trimFirstZeroFromPhone = number => {
  if (typeof number === 'string' && number.length) {
    return number[0] === '0' ? number.substring(1) : number
  }
  return number
}

export const setInitialFields = (data, setFieldsValue) => {
  const lastHyphenInPhoneIndex = data.phone?.lastIndexOf('-')
  const phone = data.phone?.substring(lastHyphenInPhoneIndex + 1)
  setFieldsValue({
    'user.name': data.name,
    'user.work_email': data.work_email,
    'user.phone': phone,
    'company.name': data.company_name,
    'company.expected_total_budget': data.total_payable_price,
    'company.size': data.size
  })
}
