/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import {
  Alert,
  Button,
  Icon,
  Form,
  Spin,
  Row,
  message
} from 'antd'
import { LayoutContentWrapper } from '../../../../../../components/utility/layoutWrapper.style'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import { ColTextAlignRight, RowWithMargin } from '../../../CommonComponents/index.style'
import UserFormFields from './components/userForm'
import CompanyFormFields from './components/companyForm'
import CompanyDocsFormFields from './components/companyDocsForm'
import { setInitialFields, trimFirstZeroFromPhone } from './utility'
import { useErrorContextValue, useGet, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../state/hooks'
import { useAddCompany } from '../../../state/AddCompany/hooks/useAddCompany'
import { addCompanyApiConfig } from '../apiConfig'

const AddCompany = ({ history, form, ...props }) => {
  const { getFieldDecorator, getFieldValue } = form
  const [leadDetail, leadDetailRequest] = useGet(addCompanyApiConfig.leadDetail)
  const [{
    COMPANY_FORM_PARAMETERS_ERROR,
    companyFormParametersStatus,
    BUSINESS_TYPES_ERROR,
    businessTypesStatus,
    CREATE_COMPANY_ERROR,
    createCompanyStatus,
    createCompanyErrorData,
    LEAD_DETAIL_ERROR,
    leadDetailStatus
  }] = useErrorContextValue()
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const {
    getCompanyFormParameters,
    companyFormParametersData,
    getBusinessTypes,
    businessTypesData,
    createCompanyData,
    createCompany
  } = useAddCompany()
  const [{ COMPANY_FORM_PARAMETERS_LOADER, CREATE_COMPANY_LOADER, LEAD_DETAIL_LOADER }] = useLoaderContextValue()
  const [dropDownOptions, setDropDownOptions] = useState({ industry: [], insuranceProviders: [], paymentMethods: [], businessTypes: [] })
  const smeLeadData = history.location.state
  const { setFieldsValue } = form

  const goBack = () => {
    history.goBack()
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      const valuesToBeSent = { ...values }
      valuesToBeSent.company.documents = {}
      if (values.company.prev_policy && Array.isArray(values.company.prev_policy)) {
        valuesToBeSent.company.documents.prev_policy = values.company.prev_policy[0]?.url
        delete valuesToBeSent.company.prev_policy
      }
      valuesToBeSent.company.expected_total_budget = String(valuesToBeSent.company.expected_total_budget || '').replace(/\./g, '').replace(',', '.')
      valuesToBeSent.company.expected_protection_start_date = values.company.expected_protection_start_date && values.company.expected_protection_start_date.format('YYYY-MM-DD')
      valuesToBeSent.user.phone = `+62-${trimFirstZeroFromPhone(values.user.phone)}`
      valuesToBeSent.company.coverage_type = valuesToBeSent.company.coverage_type.filter(coverageType => coverageType && String(coverageType).trim())
      if (smeLeadData) {
        valuesToBeSent.lead_reference_id = smeLeadData.reference_id
      }
      if (!err) {
        createCompany(valuesToBeSent)
        resetState(['createCompanyData'])
        resetError(['createCompanyData', 'createCompanyStatus', 'CREATE_COMPANY_ERROR'])
      }
    })
  }

  const handleIndustryChange = (industry) => {
    getBusinessTypes({ industry })
    form.setFieldsValue({ 'company.business_type': null })
  }

  useEffect(() => {
    if (companyFormParametersStatus === 'success' && !COMPANY_FORM_PARAMETERS_ERROR && companyFormParametersData) {
      setDropDownOptions({
        industry: companyFormParametersData.industry,
        insuranceProviders: companyFormParametersData.insurance_providers,
        paymentMethods: companyFormParametersData.payment_methods
      })
    }
  }, [companyFormParametersData, companyFormParametersStatus])

  useEffect(() => {
    if (leadDetail) {
      setInitialFields(leadDetail, setFieldsValue)
    }
  }, [leadDetail, setFieldsValue])

  useEffect(() => {
    getCompanyFormParameters()
    if (smeLeadData) {
      leadDetailRequest({ id: smeLeadData.id })
    }
    return () => {
      resetError([
        'companyFormParametersStatus',
        'COMPANY_FORM_PARAMETERS_ERROR'
      ])
    }
  }, [])

  useEffect(() => {
    if (businessTypesStatus && !BUSINESS_TYPES_ERROR && businessTypesData) {
      setDropDownOptions(options => ({ ...options, businessTypes: businessTypesData.business_types }))
    }
  }, [businessTypesData, businessTypesStatus])

  useEffect(() => {
    if (createCompanyData && createCompanyData.company_id) {
      form.resetFields()
      message.success('Company created successfully')
      history.push('/employee-benefits/company-list/')
      resetState(['createCompanyData', 'createCompanyStatus'])
      resetError(['CREATE_COMPANY_ERROR'])
    }
  }, [createCompanyData])

  useEffect(() => {
    if (CREATE_COMPANY_ERROR) {
      if (createCompanyErrorData && createCompanyErrorData.error) {
        const error = createCompanyErrorData.error
        if (error.company) {
          const { non_field_errors: nonFieldErrors, ...companyErrors } = error.company
          for (const key in companyErrors) {
            const values = form.getFieldsValue()
            form.setFields({
              [`company.${key}`]: {
                value: values.company[key],
                errors: Array.isArray(companyErrors[key]) && companyErrors[key].map(err => new Error(err))
              }
            })
          }
          if (Array.isArray(nonFieldErrors)) {
            message.error(nonFieldErrors.join('\n'))
          }
        }
        if (error.user) {
          const { non_field_errors: nonFieldErrors, ...userErrors } = error.user
          for (const key in userErrors) {
            const values = form.getFieldsValue()
            form.setFields({
              [`user.${key}`]: {
                value: values.user[key],
                errors: Array.isArray(userErrors[key]) && userErrors[key].map(err => new Error(err))
              }
            })
          }
          if (Array.isArray(nonFieldErrors)) {
            message.error(nonFieldErrors.join('\n'))
          }
        }
      }
    }
  }, [CREATE_COMPANY_ERROR, createCompanyStatus, createCompanyErrorData])

  return (
    <LayoutContentWrapper>
      <RowWithMargin>
        <Button onClick={goBack}><Icon type='arrow-left' /> Back</Button>
      </RowWithMargin>
      <LayoutContent>
        <Spin spinning={!!COMPANY_FORM_PARAMETERS_LOADER || !!CREATE_COMPANY_LOADER || !!LEAD_DETAIL_LOADER}>
          {COMPANY_FORM_PARAMETERS_ERROR && <Alert type='error' message={companyFormParametersStatus} banner />}
          {LEAD_DETAIL_ERROR && <Alert type='error' message={leadDetailStatus} banner />}
          {BUSINESS_TYPES_ERROR && <Alert type='error' message={businessTypesStatus} banner />}
          {CREATE_COMPANY_ERROR && (
            <Alert type='error' message={(createCompanyErrorData && createCompanyErrorData.message) || createCompanyStatus} banner />
          )}
          <h2>Add Company {smeLeadData?.reference_id && 'From SME Lead'}</h2>
          <Form
            onSubmit={handleSubmit}
          >
            <UserFormFields getFieldDecorator={getFieldDecorator} />
            <CompanyFormFields
              getFieldDecorator={getFieldDecorator}
              getFieldValue={getFieldValue}
              handleIndustryChange={handleIndustryChange}
              dropDownOptions={dropDownOptions}
            />
            <CompanyDocsFormFields
              getFieldDecorator={getFieldDecorator}
              form={form}
            />
            <Row gutter={8}>
              <ColTextAlignRight span={24}>
                <Button type='primary' htmlType='submit'>Submit</Button>
              </ColTextAlignRight>
            </Row>
          </Form>
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default Form.create()(AddCompany)
