
const numberFieldLengthValidationRules = [
  {
    transform: value => value && String(value).replace(/\./g, '').replace(',', '.')
  },
  {
    validator: (_, value, callback) => {
      if (!value) {
        return callback()
      }
      const [wholePart, decimalPart] = value.split('.')
      const valueAsNumber = Number(value)
      if (valueAsNumber > 0) {
        if (wholePart && wholePart.length > 9) {
          return Promise.reject(new Error('This field cannot have more than 9 digits before decimal'))
        }
        if (decimalPart && decimalPart.length > 3) {
          return Promise.reject(new Error('This field cannot have more than 3 digits after decimal'))
        }
      } else if (valueAsNumber <= 0) {
        return Promise.reject(new Error('This field should be greater than 0'))
      }
      return callback()
    }
  }
]

export default numberFieldLengthValidationRules
