import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  COMPANY_FORM_PARAMETERS_REQUEST: 'COMPANY_FORM_PARAMETERS_REQUEST',
  COMPANY_FORM_PARAMETERS: 'COMPANY_FORM_PARAMETERS',
  BUSINESS_TYPES_REQUEST: 'BUSINESS_TYPES_REQUEST',
  BUSINESS_TYPES: 'BUSINESS_TYPES',
  CREATE_COMPANY_REQUEST: 'CREATE_COMPANY_REQUEST',
  CREATE_COMPANY: 'CREATE_COMPANY',

  getCompanyFormParameters: payload => ({
    type: actions.COMPANY_FORM_PARAMETERS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      // TODO: fix url
      url: ebUrls.companyFormParameters
    }
  }),
  getBusinessTypes: payload => ({
    type: actions.BUSINESS_TYPES_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getBusinessTypes
    }
  }),
  addCompany: payload => ({
    type: actions.CREATE_COMPANY_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.createCompany
    }
  })
}

export default actions
