import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useAddCompany = () => {
  const [{
    companyFormParametersData,
    companyFormParametersStatus,
    businessTypesData,
    businessTypesStatus,
    createCompanyData,
    createCompanyStatus
  }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const getCompanyFormParameters = payload => {
    callApi(actions.getCompanyFormParameters())
  }

  const getBusinessTypes = payload => {
    callApi(actions.getBusinessTypes({ query: payload }))
  }

  const createCompany = payload => {
    callApi(actions.addCompany({ body: payload }))
  }

  return {
    companyFormParametersData,
    companyFormParametersStatus,
    getCompanyFormParameters,
    businessTypesStatus,
    businessTypesData,
    getBusinessTypes,
    createCompany,
    createCompanyData,
    createCompanyStatus
  }
}
