import React from 'react'
import { Row, Col, Typography, Input, Form, Select, DatePicker } from 'antd'
import { RowWithMargin } from '../../../../CommonComponents/index.style'
import { validationRules } from '../constants'
import { disabledDate } from '../utility'
import CustomNumberFormat from '../../../../CommonComponents/CustomNumberFormat'

const { Text } = Typography
const { Option } = Select

const CompanyFormFields = ({ getFieldDecorator, getFieldValue, handleIndustryChange, dropDownOptions }) => {
  return (
    <>
      <RowWithMargin gutter={8}>
        <Col span={24}><Text strong>Company Details</Text></Col>
        <Col span={6}>
          <Form.Item
            label='Company Type'
          >
            {
              getFieldDecorator('company.is_internal', { initialValue: false })(
                <Select>
                  <Select.Option value={!!true}>
                    Testing
                  </Select.Option>
                  <Select.Option value={false}>
                    Real
                  </Select.Option>
                </Select>
              )
            }
          </Form.Item>
        </Col>
        <Col span={6}>
          <Form.Item
            label='Company name'
          >
            {
              getFieldDecorator('company.name', {
                validateTrigger: 'onBlur',
                rules: validationRules.companyName
              })(
                <Input
                  placeholder='Pasarpolis..'
                />
              )
            }
          </Form.Item>
        </Col>
        <Col span={6}>
          <Form.Item
            label='Company size'
          >
            {getFieldDecorator('company.size', {
              initialValue: '1-10'
            })(
              <Select>
                <Option value='1-10'>1-10</Option>
                <Option value='11-50'>11-50</Option>
                <Option value='51-250'>51-250</Option>
                <Option value='>250'>{'>250'}</Option>
              </Select>
            )}
          </Form.Item>
        </Col>
        <Col span={6}>
          <Form.Item
            label='Coverage type'
            extra='Type and enter to add custom coverage type'
          >
            {getFieldDecorator('company.coverage_type', {
              initialValue: ['InPatient'],
              rules: validationRules.coverageType
            })(
              <Select
                mode='tags'
                placeholder='Type to add custom'
              >
                <Option value='InPatient'>Inpatient</Option>
                <Option value='OutPatient'>Outpatient</Option>
                <Option value='Dental'>Dental</Option>
                <Option value='Maternity'>Maternity</Option>
                <Option value='Life-Insurance'>Life Insurance</Option>
                <Option value='Optics'>Optics</Option>
              </Select>
            )}
          </Form.Item>
        </Col>
      </RowWithMargin>

      <Row gutter={8}>
        <Col span={6}>
          <Form.Item
            label='Company Industry'
          >
            {getFieldDecorator('company.industry', {
              rules: validationRules.industry
            })(
              <Select
                onChange={handleIndustryChange}
                placeholder='Select'
              >
                {Array.isArray(dropDownOptions.industry)
                  ? dropDownOptions.industry.map((industry, index) => (
                    <Option value={industry} key={index}>
                      {industry}
                    </Option>)
                    )
                  : null}
              </Select>
            )}
          </Form.Item>
        </Col>

        <Col span={6}>
          <Form.Item
            label='Company Business Type'
          >
            {getFieldDecorator('company.business_type', {
              rules: validationRules.businessTypes
            })(
              <Select
                placeholder='Select'
              >
                {Array.isArray(dropDownOptions.businessTypes)
                  ? dropDownOptions.businessTypes.map((businessType, index) => (
                    <Option value={businessType} key={index}>
                      {businessType}
                    </Option>)
                    )
                  : null}
              </Select>
            )}
          </Form.Item>
        </Col>
        <Col span={6}>
          <Form.Item
            label='Expected Total Budget'
          >
            {getFieldDecorator('company.expected_total_budget', {
              rules: validationRules.expectedTotalBudget
            })(
              <CustomNumberFormat
                placeholder='500000'
              />
            )}
          </Form.Item>
        </Col>
        <Col span={6}>
          <Form.Item
            label='Protection start date'
          >
            {getFieldDecorator('company.expected_protection_start_date', {
              rules: validationRules.expectedProtectionStartDate
            })(
              <DatePicker
                disabledDate={disabledDate}
              />
            )}
          </Form.Item>
        </Col>
      </Row>
      <Row gutter={8}>
        <Col span={6}>
          <Form.Item
            label='Desired Insurance'
          >
            {getFieldDecorator('company.desired_insurance', {
              initialValue: []
            })(
              <Select
                mode='multiple'
                placeholder='Select'
              >
                {Array.isArray(dropDownOptions.insuranceProviders)
                  ? (
                      dropDownOptions.insuranceProviders.map((provider, index) => (
                        <Option
                          value={provider}
                          key={index}
                          disabled={
                            Array.isArray(getFieldValue('company.unwanted_insurance')) &&
                            getFieldValue('company.unwanted_insurance').includes(provider)
                          }
                        >
                          {provider}
                        </Option>
                      ))
                    )
                  : null}
              </Select>
            )}
          </Form.Item>
        </Col>
        <Col span={6}>
          <Form.Item
            label='Unwanted Insurance'
          >
            {getFieldDecorator('company.unwanted_insurance', {
              initialValue: []
            })(
              <Select
                mode='multiple'
                placeholder='Select'
              >
                {Array.isArray(dropDownOptions.insuranceProviders)
                  ? (
                      dropDownOptions.insuranceProviders.map((provider, index) => (
                        <Option
                          value={provider}
                          key={index}
                          disabled={
                            Array.isArray(getFieldValue('company.desired_insurance')) &&
                            getFieldValue('company.desired_insurance').includes(provider)
                          }
                        >
                          {provider}
                        </Option>
                      ))
                    )
                  : null}
              </Select>
            )}
          </Form.Item>
        </Col>
        <Col span={6}>
          <Form.Item
            label='Preferred Payment Method'
          >
            {getFieldDecorator('company.preferred_payment_method', {
              rules: validationRules.preferredPaymentMode
            })(
              <Select
                placeholder='Select'
              >
                {
                  Array.isArray(dropDownOptions.paymentMethods)
                    ? (
                        dropDownOptions.paymentMethods.map((paymentMethod, index) => (
                          <Option value={paymentMethod} key={index}>{paymentMethod}</Option>
                        ))
                      )
                    : null
                }
              </Select>
            )}
          </Form.Item>
        </Col>
      </Row>
    </>
  )
}

export default CompanyFormFields
